INSERT INTO settings(key,value) VALUES('subscription_plan','{"enabled":false,"name":"Admin platform subscription","amount_minor":0,"currency":"KES","period_days":30,"version":"initial","terms":"Renewal adds the stated number of days after verified payment. Payments are initiated by the administrator through Pesapal."}') ON CONFLICT(key) DO NOTHING;
CREATE TABLE subscription_orders(id text PRIMARY KEY, admin_id text NOT NULL REFERENCES users(id), plan_name text NOT NULL, plan_version text NOT NULL, terms text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), currency text NOT NULL DEFAULT 'KES', period_days integer NOT NULL CHECK(period_days BETWEEN 1 AND 366), status text NOT NULL DEFAULT 'initiated' CHECK(status IN ('initiated','pending','submission_unknown','failed','completed','reversed','needs_review')), receipt_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX subscription_orders_owner ON subscription_orders(admin_id,created_at DESC);
CREATE TABLE subscription_attempts(id text PRIMARY KEY, order_id text NOT NULL UNIQUE REFERENCES subscription_orders(id), tracking_id text UNIQUE, redirect_url text, state text NOT NULL DEFAULT 'initiated', checked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscription_periods(id text PRIMARY KEY, order_id text NOT NULL UNIQUE REFERENCES subscription_orders(id), admin_id text NOT NULL REFERENCES users(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, CHECK(ends_at>starts_at));
CREATE INDEX subscription_periods_access ON subscription_periods(admin_id,revoked,starts_at,ends_at);
CREATE TABLE subscription_events(id text PRIMARY KEY, attempt_id text NOT NULL REFERENCES subscription_attempts(id), provider_status integer NOT NULL, reference text NOT NULL DEFAULT '', amount_minor integer NOT NULL, currency text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscription_reminders(id text PRIMARY KEY, admin_id text NOT NULL REFERENCES users(id), period_id text NOT NULL REFERENCES subscription_periods(id), kind text NOT NULL CHECK(kind IN ('expiring','expired')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(admin_id,period_id,kind));
